class FMCreateCustomerAction extends FMCustomerPage
{
    private  str firstName;
    private str lastName;
    private str custEmail;
    private str driversLicense;
    private str cellPhone;
    private str custAddressLine1;
    private str city;
    private  str state;
    private int zipCode;
    private str countryRegion;

}

Method.Source:
[SysAppField(fieldStr(FMCustomer, FirstName), "First name")]
public str customerFirstName(str _value=firstName)
{
    firstName = _value;
    return firstName;
}

[SysAppField(fieldStr(FMCustomer, LastName), "Last name")]
public str customerLastName(str _value=lastName)
{
    lastName = _value;
    return lastName;
}

[SysAppField(fieldStr(FMCustomer, DriverLicense), "Drivers license")]
public str driverLicenseNumber(str _value=driversLicense)
{
    driversLicense = _value;
    return driversLicense;
}

[SysAppField(fieldStr(FMCustomer, CellPhone), "Phone")]
public str customerPhone(str _value=cellPhone)
{
    cellPhone = _value;
    return cellPhone;
}

[SysAppField(fieldStr(FMCustomer, Email), "Email")]
public str customerEmail(str _value=custEmail)
{
    custEmail = _value;
    return custEmail;
}

[SysAppProjection("Address line 1")]
public str addressLine1(str _value=custAddressLine1)
{
    custAddressLine1 = _value;
    return custAddressLine1;
}

[SysAppProjection("City")]
public str addressCity(str _value=city)
{
    city = _value;
    return city;
}

[SysAppProjection("State")]
public str addressState(str _value=state)
