    return zipCode;
}

[SysAppProjection("Country / region")]
public str addressCountryRegion(str _value=countryRegion)
{
    countryRegion = _value;
    return countryRegion;
}

public boolean validate(SysAppResponse _response)
{
    boolean validationPassed = true;

    if (this.customerFirstName() == "")
    {
        //You can directly add messages to response or use info(), warning() and error() functions to log messages.
        //Messages logged by infolog will also be captured and shown to mobile client
        _response.addMessage(new SysAppResponseMessage("Customer first name should be specified", SysAppMessageType::Error));
        validationPassed = false;
    }

    if (this.customerLastName() == "")
    {
        _response.addMessage(new SysAppResponseMessage("Customer last name should be specified", SysAppMessageType::Error));
        validationPassed = false;
    }

    if (this.customerEmail() == "")
    {
        //Messages logged by infolog will also be captured and shown to mobile client
        warning("EMail is not provided");
        error("EMail is not provided");
        info("EMail is not provided");
        validationPassed = false;
    }

    return validationPassed;
}

public SysAppResponse addCustomer(SysAppEntityContext _entityContext, List _filterContextList)
{
    SysAppResponse response = new SysAppResponse();

    if (this.validate(response))
    {            
        FMCustomer customerTable;
        FMAddressTable addressTable;

        ttsbegin;
        customerTable.FirstName = this.customerFirstName();
        customerTable.LastName = this.customerLastName();
        customerTable.DriverLicense = this.driverLicenseNumber();
        customerTable.Email = this.customerEmail();

        addressTable.AddressLine1 = this.addressLine1();
        addressTable.City = this.addressCity();
        addressTable.State = this.addressState();
        addressTable.ZipCode = this.addressZipCode();
        addressTable.Country = this.addressCountryRegion();
        addressTable.Insert();

        customerTable.AddressID = addressTable.RecId;
        customerTable.Insert();
        ttscommit;

        //Need to add a commit on the entity datasource. This records the recId of the entity comitted and it will be sent back to mobile client.
        response.addCommit(SysAppEntityContext::constructFromBuffer(customerTable));
    }

    return response;
}
